export default function WorkspaceIndex() { return <main className="mx-auto min-h-screen max-w-6xl px-6 py-12"><p className="font-bold text-[#1738a8]">Daily Essential.SCHOOL</p><h1 className="mt-2 text-3xl font-bold">Role workspaces</h1><p className="mt-3 max-w-2xl text-slate-600">Every role has a scoped workspace. Roles can be assigned in more than one scope; access is never determined by a single user-role field.</p><div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{roleCatalog.map(([slug, name, group]) => <Link className="rounded-lg border border-slate-200 bg-white p-4 hover:border-[#1738a8]" key={slug} href={`/workspace/${slug}`}><p className="font-semibold">{name}</p><p className="mt-1 text-sm text-slate-500">{group}</p></Link>)}</div></main>; }
